package witchinggadgets;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.item.component.*;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.crafting.*;
@GameTestHolder(WitchingGadgets.ID)
@PrefixGameTestTemplate(false)
public final class IntegrationGameTests {
    @GameTest(template="test/platform") public static void optionalMetalsRegisterAfterTags(GameTestHelper h){for(var element:PortData.read("content")){var o=element.getAsJsonObject();String name=PortData.str(o,"id");if(!name.startsWith("native_")||!Compat.visible(name))continue;String metal=name.substring(7,name.length()-8);h.assertTrue(TcRecipes.get("WG:CLUSTER_"+metal)!=null,"missing tagged metal recipe: "+metal);}h.succeed();}
    @GameTest(template="test/platform") public static void fluidCapsuleUsesWholeBuckets(GameTestHelper h){var stack=Content.stack("crystal_capsule");var handler=Capsule.handler(stack);var water=new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000);var execute=net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE;h.assertValueEqual(handler.fill(water.copyWithAmount(500),execute),0,"partial bucket accepted");h.assertValueEqual(handler.fill(water,execute),1000,"full bucket rejected");h.assertTrue(handler.drain(500,execute).isEmpty(),"partial bucket drained");h.assertValueEqual(handler.drain(1000,execute).getAmount(),1000,"full bucket lost");h.assertTrue(handler.getFluidInTank(0).isEmpty(),"capsule did not empty");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceProcessesCinnabar(GameTestHelper h){var m=form(h);m.items.setStackInSlot(0,new ItemStack(Content.tc("native_cinnabar_cluster")));for(int i=0;i<440;i++)m.blast(h.getLevel());h.assertValueEqual(Port5Tests.dropped(h,m,Content.tc("quicksilver")),3,"cinnabar must eject three quicksilver");h.assertTrue(m.items.getStackInSlot(2).isEmpty(),"product stayed in removed GUI");h.succeed();}
    @GameTest(template="test/platform") public static void automationCannotInsertIntoOutput(GameTestHelper h){var m=PortGameTests.place(h,"spinning_wheel");var cap=h.getLevel().getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,m.getBlockPos(),Direction.UP);h.assertTrue(cap!=null,"automation missing");var rest=cap.insertItem(5,new ItemStack(Items.DIAMOND),false);h.assertTrue(!rest.isEmpty()&&m.items.getStackInSlot(5).isEmpty(),"automation inserted into output");h.succeed();}
    @GameTest(template="test/platform") public static void gogglesUpgradeImplementsThaumcraftRevealer(GameTestHelper h){var helmet=Content.stack("primordial_helm");var output=InfusionCrafting.result(h.getLevel(),InfusionCrafting.TYPE_RECIPE,"WG:HELMGOGGLES_PRIMORDIAL",helmet);var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);h.assertTrue(output.getItem() instanceof thaumcraft.node.Revealer r&&r.showNodes(output,p),"goggles are only cosmetic");h.assertTrue(thaumcraft.item.armor.FortressArmorItem.hasGoggles(output),"Thaumcraft upgrade component missing");h.succeed();}
    static BlockPos furnace(GameTestHelper h){BlockPos root=new BlockPos(3,2,3);for(int y=0;y<3;y++)for(int z=-1;z<=1;z++)for(int x=-1;x<=1;x++){var s=y<2?Multiblock.expectedBrick(y*9+(z+1)*3+x+1).defaultBlockState():x==0&&z==0?Blocks.LAVA.defaultBlockState():Blocks.NETHER_BRICK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,x<0?Direction.EAST:x>0?Direction.WEST:z<0?Direction.SOUTH:Direction.NORTH);h.setBlock(root.offset(x,y,z),s);}return root;}
    static MachineEntity form(GameTestHelper h){var root=furnace(h);var p=h.makeMockPlayer(net.minecraft.world.level.GameType.CREATIVE);h.assertTrue(Multiblock.tryForm(h.getLevel(),h.absolutePos(root.offset(-1,0,-1)),p,new ItemStack(Content.tc("wand"))),"complete furnace failed to form");return h.getBlockEntity(root);}
    @GameTest(template="test/platform") public static void furnaceFormsTwentySevenParts(GameTestHelper h){var m=form(h);for(int y=0;y<3;y++)for(int z=-1;z<=1;z++)for(int x=-1;x<=1;x++){var part=h.getLevel().getBlockEntity(m.getBlockPos().offset(x,y,z));h.assertTrue(part instanceof MachineEntity p&&m.master.equals(p.master),"missing furnace part");}h.assertValueEqual(m.position,4,"wrong furnace controller");h.succeed();}
    @GameTest(template="test/platform") public static void incompleteFurnaceIsRejected(GameTestHelper h){var root=furnace(h);h.setBlock(root.offset(-1,0,-1),Blocks.DIRT);h.assertTrue(!Multiblock.valid(h.getLevel(),h.absolutePos(root)),"incorrect brick accepted");h.succeed();}
    @GameTest(template="test/platform") public static void brokenFurnaceRestoresOriginalMaterials(GameTestHelper h){var m=form(h);BlockPos root=m.getBlockPos();h.getLevel().removeBlock(root,false);h.assertTrue(h.getLevel().getBlockState(root.offset(-1,0,-1)).is(Blocks.NETHER_BRICKS),"brick not restored");h.assertTrue(h.getLevel().getBlockState(root.offset(0,1,0)).is(Blocks.SOUL_SAND),"soul sand not restored");h.assertTrue(h.getLevel().getBlockState(root.above(2)).is(Blocks.LAVA),"lava not restored");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceTriplesNativeIron(GameTestHelper h){var m=form(h);m.items.setStackInSlot(0,new ItemStack(Content.tc("native_iron_cluster")));for(int i=0;i<440;i++)m.blast(h.getLevel());h.assertTrue(m.items.getStackInSlot(0).isEmpty(),"cluster not consumed");h.assertValueEqual(Port5Tests.dropped(h,m,Items.IRON_INGOT),3,"wrong ejected furnace yield");h.assertTrue(m.items.getStackInSlot(2).isEmpty(),"product stayed in removed GUI");h.succeed();}
    @GameTest(template="test/platform") public static void furnaceControllerSurvivesReload(GameTestHelper h){var m=form(h);var nbt=m.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new MachineEntity(m.getBlockPos(),m.getBlockState());restored.loadWithComponents(nbt,h.getLevel().registryAccess());h.assertTrue(m.master.equals(restored.master)&&m.original.equals(restored.original),"multiblock persistence failed");h.assertValueEqual(restored.position,4,"controller position lost");h.succeed();}
    @GameTest(template="test/platform") public static void dyeingPreservesContentsAndOwner(GameTestHelper h){var bag=Content.stack("bag_of_tricks");var owner=UUID.randomUUID();var t=Data.get(bag);t.putUUID("Owner",owner);Data.put(bag,t);var storage=new BagItem.Storage(bag,18);storage.setItem(0,new ItemStack(Items.DIAMOND,9));var input=CraftingInput.of(2,1,List.of(bag,new ItemStack(Items.RED_DYE)));var recipe=h.getLevel().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,input,h.getLevel()).orElseThrow();var output=recipe.value().assemble(input,h.getLevel().registryAccess());h.assertTrue(output.has(DataComponents.DYED_COLOR),"dye did not apply");h.assertTrue(Data.get(output).getUUID("Owner").equals(owner),"owner lost");h.assertValueEqual(new BagItem.Storage(output,18).getItem(0).getCount(),9,"dyeing lost stored items");h.succeed();}
    @GameTest(template="test/platform") public static void kamaConversionPreservesRunesAndStorage(GameTestHelper h){var cloak=Content.stack("cloak_of_voluminous_pockets");Data.integer(cloak,"Runes",4);var storage=new BagItem.Storage(cloak,27);storage.setItem(7,new ItemStack(Items.EMERALD,6));var output=new DynamicRecipes().result(List.of(cloak,new ItemStack(Content.tc("mundane_belt"))));h.assertTrue(output.is(Content.item("kama_of_voluminous_pockets")),"wrong kama");h.assertValueEqual(Data.get(output).getInt("Runes"),4,"cloak data lost");h.assertValueEqual(new BagItem.Storage(output,27).getItem(7).getCount(),6,"cloak storage lost");h.succeed();}
    @GameTest(template="test/platform") public static void helmetInfusionKeepsExistingComponents(GameTestHelper h){var helmet=Content.stack("primordial_helm");Data.integer(helmet,"Affinity",5);helmet.setDamageValue(42);var result=InfusionCrafting.result(h.getLevel(),InfusionCrafting.TYPE_RECIPE,"WG:HELMGOGGLES_PRIMORDIAL",helmet);h.assertValueEqual(Data.get(result).getInt("goggles"),1,"goggles not installed");h.assertValueEqual(Data.get(result).getInt("Affinity"),5,"affinity lost");h.assertValueEqual(result.getDamageValue(),42,"damage changed");h.succeed();}
    @GameTest(template="test/platform") public static void primordialCraftingReturnsPearlsOnlyOnce(GameTestHelper h){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(h.getLevel());p.getInventory().clearContent();var output=Content.stack("primordial_claymore");thaumcraft.infusion.InfusionHooks.onInfusionCrafted(p,output);thaumcraft.infusion.InfusionHooks.onInfusionCrafted(p,output);h.assertValueEqual(p.getInventory().countItem(Content.item("powerless_pearl")),2,"pearls lost or duplicated");h.succeed();}
    @GameTest(template="test/platform") public static void ogivalCutUsesAffinityAndConsumesIngredients(GameTestHelper h){var m=PortGameTests.place(h,"cutting_table");m.items.setStackInSlot(0,new ItemStack(Items.DIAMOND));var phial=new ItemStack(Content.tc("essentia_phial"));thaumcraft.aspect.AspectKeys.ASPECTS.set(phial,new AspectList().add(Aspect.ORDER,8));m.items.setStackInSlot(1,phial);m.gemCut=1;m.cutGem();var output=m.items.getStackInSlot(4);h.assertTrue(output.getItem() instanceof GemItem,"cut output missing");h.assertTrue(GemItem.aspect(output)==Aspect.ORDER,"wrong aspect");h.assertValueEqual(Data.get(output).getInt("Cut"),1,"wrong cut");h.assertTrue(m.items.getStackInSlot(0).isEmpty()&&m.items.getStackInSlot(1).isEmpty(),"ingredients not consumed");h.succeed();}
    @GameTest(template="test/platform") public static void connectedWallsShareRedstone(GameTestHelper h){var first=new BlockPos(2,2,2);h.setBlock(first,Content.block("ethereal_wall"));h.setBlock(first.east(),Content.block("ethereal_wall"));h.setBlock(first.west(),Blocks.REDSTONE_BLOCK);h.assertTrue(WallNet.powered(h.getLevel(),h.absolutePos(first.east())),"redstone did not reach connected wall");h.succeed();}
    @GameTest(template="test/platform") public static void tinkererReceivesFiveEnchantments(GameTestHelper h)throws Exception{if(Compat.enabled("thaumictinkerer")){var manager=Class.forName("thaumictinkerer.enchanting.EnchantmentManager");Map<?,?> data=(Map<?,?>)manager.getMethod("data").invoke(null);for(String name:List.of("translucency","unveiling","stealth","backstabbing","throwoff"))h.assertTrue(data.containsKey(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.ENCHANTMENT,WitchingGadgets.id(name))),"enchantment not registered in Tinkerer: "+name);}h.succeed();}
}
